    <section class="panel" aria-labelledby="support-title">
      <h1 id="support-title">Contact Support</h1>
      <p class="intro">Send us your details and we will get back to you as soon as possible.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
          <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-describedby="full-name-error" placeholder="Jane Doe">
          <p class="error-text" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
          <input id="email-address" name="emailAddress" type="email" autocomplete="email" required aria-describedby="email-address-error" placeholder="jane@example.com">
          <p class="error-text" id="email-address-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number</label>
          <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-number-help phone-number-error" placeholder="+1 (555) 123-4567">
          <p class="help-text" id="phone-number-help">Optional. Use digits, spaces, dashes, parentheses, or a leading +. Example: +1 (555) 123-4567.</p>
          <p class="error-text" id="phone-number-error" aria-live="polite"></p>
