 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="panel" aria-labelledby="support-title">
       <h1 id="support-title">Contact Support</h1>
       <p class="intro">Send us your details and we will get back to you as soon as possible.</p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
           <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-describedby="full-name-error" placeholder="Jane Doe">
           <p class="error-text" id="full-name-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
           <input id="email-address" name="emailAddress" type="email" autocomplete="email" required aria-describedby="email-address-error" placeholder="jane@example.com">
           <p class="error-text" id="email-address-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="phone-number">Phone number</label>
           <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-number-help phone-number-error" placeholder="+1 (555) 123-4567">
           <p class="help-text" id="phone-number-help">Optional. Use digits, spaces, dashes, parentheses, or a leading +. Example: +1 (555) 123-4567.</p>
           <p class="error-text" id="phone-number-error" aria-live="polite"></p>
         </div>

         <div class="actions">
           <button type="submit">Send message</button>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const fields = {
       fullName: {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Full name is required.';
           }

           return '';
         }
       },
       emailAddress: {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate(value) {
           if (!value.trim()) {
             return 'Email address is required.';
           }

           if (!fields.emailAddress.input.validity.valid) {
             return 'Enter a valid email address.';
           }

           return '';
         }
       },
       phoneNumber: {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         validate(value) {
           if (!value.trim()) {
             return '';
           }

           const phonePattern = /^\+?[0-9()\-\s.]{7,}$/;
           if (!phonePattern.test(value.trim())) {
             return 'Enter a valid phone number, such as +1 (555) 123-4567.';
           }

           return '';
         }
       }
     };

     function validateField(field) {
       const message = field.validate(field.input.value);
       field.error.textContent = message;
       field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
       return !message;
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener('blur', () => validateField(field));
       field.input.addEventListener('input', () => {
         if (field.error.textContent) {
           validateField(field);
         }
       });
     });

     form.addEventListener('submit', (event) => {
       const orderedFields = [fields.fullName, fields.emailAddress, fields.phoneNumber];
       const firstInvalid = orderedFields.find((field) => !validateField(field));

       if (firstInvalid) {
         event.preventDefault();
         firstInvalid.input.focus();
       }
     });
   </script>
 </body>
 </html>

